class Solution {
    public int[][] divideArray(int[] nums,int k){
        Arrays.sort(nums);
        int[][] answer=new int[nums.length/3][3];
        for(int group=0;group<answer.length;group++){
            int start=group*3;
            if(nums[start+2]-nums[start]>k)return new int[0][0];
            answer[group][0]=nums[start];
            answer[group][1]=nums[start+1];
            answer[group][2]=nums[start+2];
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun divideArray(nums:IntArray,k:Int):Array<IntArray>{
        nums.sort();
        val answer=Array(nums.size/3){
            IntArray(3)
        };
        for(group in answer.indices){
            val start=group*3;
            if(nums[start+2]-nums[start]>k)return emptyArray<IntArray>();
            answer[group][0]=nums[start];
            answer[group][1]=nums[start+1];
            answer[group][2]=nums[start+2]
        };
        return answer
    }
}

